struct Node {
    Node* ch[26] = {};
    bool isEnd = false;
};

void insert(Node* root, const string& w){
    Node* cur = root;
    for (char c : w) {
        int i = c - 'a';
        if (!cur->ch[i]) cur->ch[i] = new Node();
        cur = cur->ch[i];                 // descend/create
    }
    cur->isEnd = true;                    // word completes here
}
bool search(Node* root, const string& w){
    Node* n = walk(root, w);
    return n && n->isEnd;
}
bool startsWith(Node* root, const string& p){
    return walk(root, p) != nullptr;      // path exists = enough
}

