class TrieNode:
    def __init__(self):
        self.ch = {}                 # char -> child node
        self.is_end = False

root = TrieNode()

def insert(word):
    cur = root
    for c in word:
        cur = cur.ch.setdefault(c, TrieNode())
    cur.is_end = True

def search(word):
    n = walk(word)
    return n is not None and n.is_end

def starts_with(p):
    return walk(p) is not None

def walk(p):
    cur = root
    for c in p:
        if c not in cur.ch: return None
        cur = cur.ch[c]
    return cur
